<?php
declare(strict_types=1);namespace LittyWatch\Controllers;use LittyWatch\Core\{Request,Response,View};use LittyWatch\Repositories\PlatformRepository;final class TraderController{public function __construct(private readonly PlatformRepository $repo,private readonly View $view){}public function index(Request $r):Response{$q=$r->string('q');return Response::html($this->view->render('traders/index',['title'=>'Traders · LittyWatch','rows'=>$this->repo->traders($q),'query'=>$q]));}public function show(Request $r):Response{$name=$r->string('name');if($name==='')return Response::html('Trader ontbreekt',400);return Response::html($this->view->render('traders/show',['title'=>$name.' · LittyWatch','name'=>$name]+$this->repo->trader($name)));}}